    assert.equal(res.statusCode, 201);
    assert.equal(JSON.parse(res.body).projectPath, await realpath(persistentProject));
  });

  it('list, detail, and trash reads lazily persist remapped runtime paths', async () => {
    const runtimeRoot = join(process.cwd(), '.replaced-runtime');
    const workspaceRoot = await createTempWorkspace();
    process.env.CAT_CAFE_RUNTIME_ROOT = runtimeRoot;
    process.env.CAT_CAFE_WORKSPACE_ROOT = workspaceRoot;
    const thread = threadStore.create('alice', 'Old runtime thread', runtimeRoot);

    const list = await app.inject({ method: 'GET', url: '/api/threads', headers: { 'x-cat-cafe-user': 'alice' } });
    assert.equal(JSON.parse(list.body).threads.find((item) => item.id === thread.id).projectPath, workspaceRoot);
    assert.equal(threadStore.get(thread.id).projectPath, workspaceRoot);

    threadStore.updateProjectPath(thread.id, runtimeRoot);
    const detail = await app.inject({ method: 'GET', url: `/api/threads/${thread.id}` });
    assert.equal(JSON.parse(detail.body).projectPath, workspaceRoot);
    assert.equal(threadStore.get(thread.id).projectPath, workspaceRoot);

    threadStore.softDelete(thread.id);
    threadStore.updateProjectPath(thread.id, runtimeRoot);
    const trash = await app.inject({
      method: 'GET',
      url: '/api/threads?deleted=true',
      headers: { 'x-cat-cafe-user': 'alice' },
    });
    assert.equal(JSON.parse(trash.body).threads.find((item) => item.id === thread.id).projectPath, workspaceRoot);
    assert.equal(threadStore.get(thread.id).projectPath, workspaceRoot);
  });

